p-class.text:
@startuml
title Library
skinparam classAttributeIconSize 0
package "Catalogue" {
  abstract class Item <<entity>> {
    -id : long
    +title : String
    {abstract} +loanPeriod() : int
  }
  class Book extends Item {
    +isbn : String
  }
  interface Lendable
  enum Format {
    PRINT
    EBOOK
  }
}
class Member #ffeecc {
  String name
  +borrow(item : Item) : Loan
}
class Loan
Book ..|> Lendable
Member "1" -- "0..*" Loan : holds >
Loan --> "1" Item
Loan *-- Format
note "Members borrow items" as N1
N1 .. Member
note right of Book : printed or e-book
@enduml

