p-state.text:
@startuml
[*] --> Idle
state "Working hard" as Active {
  [*] --> Running
  Running --> Paused : pause
  Paused --> Running : resume [allowed] / log
}
Idle --> Active : start
state Check <<choice>>
Active --> Check
Check --> [*]
note left of Idle : waiting
@enduml

