sql-shop.text:
-- Online shop
CREATE TABLE customer (
  id SERIAL PRIMARY KEY,
  email VARCHAR(120) NOT NULL UNIQUE,
  name VARCHAR(80)
);
CREATE TABLE "order" (
  id BIGINT NOT NULL,
  customer_id INT NOT NULL REFERENCES customer(id),
  placed_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
  total NUMERIC(10, 2),
  CONSTRAINT order_pk PRIMARY KEY (id)
);
CREATE TABLE order_line (
  order_id BIGINT NOT NULL,
  line_no INT NOT NULL,
  product_id INT,
  qty INT NOT NULL CHECK (qty > 0),
  PRIMARY KEY (order_id, line_no),
  FOREIGN KEY (order_id) REFERENCES "order"(id) ON DELETE CASCADE
);
CREATE TABLE product (id INT PRIMARY KEY, sku VARCHAR(20) UNIQUE);
CREATE INDEX order_customer ON "order"(customer_id);
ALTER TABLE order_line ADD CONSTRAINT line_product FOREIGN KEY (product_id) REFERENCES product(id);

